\begin{equation}\label{ri:hamiltonians}
\begin{aligned}
 h_*&=h_0+R_*,\qquad \delta R=R_*-\widehat R,\\
 h_c&=h_0+\delta R,\qquad
 \widehat h=h_0+\widehat R=h_*-\delta R.
\end{aligned}
\end{equation}

\begin{equation}\label{ri:budgets}
\begin{aligned}
 h_c\circ\mathcal T_A&=H_{\rm NF}^{1}+P_A,\\
 P_A&=R_6^{1}+\delta R\circ\mathcal T_A,\\
 \widehat h\circ\mathcal T_B&=H_{\rm NF}^{\kappa_*}+P_B,\\
 P_B&=R_6^{\kappa_*}-\delta R\circ\mathcal T_B,\\
 \epsilon_A&=\norm{R_6^{1}}_{\mathcal D_A}+b_R^A,\\
 \epsilon_B&=\norm{R_6^{\kappa_*}}_{\mathcal D_B}+b_R^B.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:birkhoff}
\begin{aligned}
 \mathcal K_{ij}&=\partial_{z_i}\mathcal R_j-
                  \partial_{z_j}\mathcal R_i,\\
 \mathcal K\dot z&=\nabla_z\mathcal B+\partial_t\mathcal R=:b.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:compatibility}
\begin{aligned}
 \partial_k\mathcal K_{ij}+\partial_i\mathcal K_{jk}
                +\partial_j\mathcal K_{ki}&=0,\\
 \partial_t\mathcal K_{ij}&=\partial_i b_j-\partial_j b_i.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:transport}
\begin{aligned}
 \partial_t\mathcal R+(D_z\mathcal R)f+(D_zf)^{\mathsf T}\mathcal R&=0,\\
 \mathcal R(z,t_0)=\mathcal R_0(z),\qquad
 \mathcal B&=\mathcal R^{\mathsf T}f.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:transport-substitution}
\begin{aligned}
 \partial_i\mathcal B+\partial_t\mathcal R_i
 &=(\partial_i\mathcal R_j)f^j+\mathcal R_j\partial_i f^j\\
 &\quad-f^j\partial_j\mathcal R_i-\mathcal R_j\partial_i f^j
 =\mathcal K_{ij}f^j.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:weighted-hamiltonian}
\begin{aligned}
 \mathcal R&=(a p,0),\qquad \mathcal B=aH,
       \qquad\mathcal K=-aJ,\\
 \Pi&=a p,\qquad
 \widetilde H(q,\Pi,t)=a(t)H(q,\Pi/a(t),t).
\end{aligned}
\end{equation}

\begin{equation}\label{struct:general-chart}
 (D\mathcal C_t)^{\mathsf T}\mathcal K_0D\mathcal C_t
       =\mathcal K(z,t),\qquad \mathcal K_0=-J.
\end{equation}

\begin{equation}\label{struct:endpoint-variables}
\begin{aligned}
 \widehat w&=(\widehat Q,\widehat P)=\mathsf E(Z_+-Z_-),\\
 w&=T_0\bar Z=(Q,P)=(\bar q,-\bar\Pi).
\end{aligned}
\end{equation}

\begin{equation}\label{struct:chart-field}
\begin{aligned}
 f_Z(Z,t)&=\left[\partial_t\mathcal C_t+D\mathcal C_t f\right]
                         _{z=\mathcal C_t^{-1}(Z)},\\
 \mathcal K_0 f_Z&=\nabla_Z\mathcal H.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:mechanical-midpoint}
\begin{aligned}
 q_+-q_-&=\Delta_t M(\bar q)^{-1}\bar p,\\
 p_+-p_-&=\Delta_t[-H_q(\bar q,\bar p)-C_m\bar v]\\
           &\quad+\Delta_t(F_m+U_m),\\
 \bar v&=M(\bar q)^{-1}\bar p.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:effective-matrices}
\begin{aligned}
 q&=X,\qquad p=Y,\\
 M_{\rm eff}&=\mathsf N^{-1},\qquad
 C_{\rm eff}=\gamma\mathsf N^{-1}.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:objects}
\begin{aligned}
 g(s)&=1-\cos s-s^2/2,\\
 V_0(X)&=\tfrac12X^{\mathsf T}\mathsf N X+g(d^{\mathsf T}X),\\
 h_0(X,Y)&=\tfrac12Y^{\mathsf T}\mathsf N Y+V_0(X),\\
 h_*&=h_0+R_*,\qquad \widehat h=h_0+\widehat R,\\
 \delta R&=R_*-\widehat R,\qquad h_c=h_0+\delta R.
\end{aligned}
\end{equation}

\begin{equation}\label{struct:integral-design}
\begin{aligned}
 y_\ell={}&c_{\ell Y}(b_\ell)-c_{\ell Y}(a_\ell)\\
   &+\int_{a_\ell}^{b_\ell}
      [\nabla V_0(c_{\ell X})-U_\ell^{\rm data}]\dd\tau,\\
 D_\ell={}&-\int_{a_\ell}^{b_\ell}
          [\mathcal V_F(c_{\ell X}),c_{\ell Y}]\dd\tau,\\
 \widehat\theta={}&(\widehat\beta_1,\ldots,\widehat\beta_m,
                      \widehat\gamma)^{\mathsf T}.
\end{aligned}
\end{equation}

