\begin{equation}\label{ss:general-variational}
\begin{aligned}
 \frac{\partial L_{\rm B}}{\partial z_i}
 -\frac{\dd}{\dd t}\frac{\partial L_{\rm B}}{\partial\dot z_i}
 &=(\partial_i\mathcal R_j-\partial_j\mathcal R_i)\dot z_j\\
 &\quad-\partial_i\mathcal B-\partial_t\mathcal R_i\\
 &=\mathcal K_{ij}\dot z_j-b_i.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:general-gauge}
\begin{aligned}
 \sigma(z,t)&=\int_{t_0}^{t}[\mathcal B(z,s)-H(z,s)]\dd s,\\
 \widetilde{\mathcal R}&=\mathcal R+\nabla_z\sigma,\qquad
 \widetilde{\mathcal B}=\mathcal B-\partial_t\sigma=H.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:general-moser}
\begin{aligned}
 \mathcal K_{\lambda,t}&=\mathcal K_0+\lambda(\mathcal K_t-\mathcal K_0),\\
 \mathcal K_{\lambda,t}v_{\lambda,t}&=\mathcal R_t-\mathcal R_0,\\
 \frac{\dd\rho_{\lambda,t}}{\dd\lambda}
     &=v_{\lambda,t}\circ\rho_{\lambda,t},\qquad \rho_{0,t}=\mathrm{id}.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:general-endpoint-Jacobian}
 D\alpha=\begin{pmatrix}
 \mathsf E T_+&-\mathsf E T_-\\
 T_0T_+/2&T_0T_-/2
 \end{pmatrix}.
\end{equation}

\begin{equation}\label{ss:general-structure-residual}
\begin{aligned}
 e_{\rm B}&=\mathcal K_{\rm a}f-\partial_t\mathcal R_{\rm a}
                             -\nabla\mathcal B_{\rm a},\\
 f_{\rm a}&=\mathcal K_{\rm a}^{-1}
                 (\nabla\mathcal B_{\rm a}+\partial_t\mathcal R_{\rm a})\\
          &=f-\mathcal K_{\rm a}^{-1}e_{\rm B}.
\end{aligned}
\end{equation}

\begin{equation}
 \begin{split}
 X'&=\mathsf NY,\\
 Y'&=-\mathsf NX-\kappa d[\sin(d^{\mathsf T}X)-d^{\mathsf T}X]
       -\gamma Y.
 \end{split}
 \label{gsn:magnetic-field}
\end{equation}

\begin{equation}
 \begin{gathered}
 F_\chi(u,\tau_m)=
 \binom{e^{-\gamma\tau_m}\mathsf NP}
 {-e^{\gamma\tau_m}\nabla_X V_\kappa(X)},\\
 V_\kappa=\tfrac12X^{\mathsf T}\mathsf NX+\kappa g(d^{\mathsf T}X).
 \end{gathered}
 \label{gsn:magnetic-chart-field}
\end{equation}

\begin{equation}
 \begin{split}
 \mathcal K_y(t)&=e^{-A_s^{\mathsf T}t}\mathcal K_0e^{-A_st},\\
 \mathcal K_z(z,t)&=D\xi(z)^{\mathsf T}\mathcal K_y(t)D\xi(z).
 \end{split}
 \label{gsn:specified-K}
\end{equation}

\begin{equation}
 \begin{split}
 C_m&=(I-\Delta L_m/2)^{-1}(I+\Delta L_m/2),\\
 y_+&=T(t+\Delta)^{-1}C_mT(t)y_-,\\
 z_+&=\xi^{-1}(y_+),\qquad L_m=L(t+\Delta/2).
 \end{split}
 \label{gsn:synthetic-update}
\end{equation}

\begin{align}
 \rho A_c r_{tt}&=n_s+f_{\rm mag}+f_{\rm h}+f_{\rm c}+\rho A_c g,\\
 \partial_t(D\mathcal J_b\omega_b)&=m_s+r_s\times n+\tau_{\rm ext}.
 \label{sm:rod-balances}
\end{align}

\begin{align}
 m_d&=\tfrac12\int \xi\times j(\xi)\dd V,\nonumber\\
 F&=\nabla_r[m_d\cdot B_{\rm ext}(r)]+R_F,\nonumber\\
 \tau&=m_d\times B_{\rm ext}(r)+R_\tau.
 \label{sm:dipole-expansion}
\end{align}

\begin{align}
 M_{ij}(q)&=\int_0^L
     [\rho A_c\,r_i\cdot r_j+\psi_i^{\mathsf T}\mathcal J_b\psi_j]\dd s,
       \nonumber\\
 Q_i&=\int_0^L[f\cdot r_i+\tau\cdot D\psi_i]\dd s+Q_i^\partial.
 \label{sm:galerkin-metric}
\end{align}

\begin{equation}
 \dot H=-v^{\mathsf T}\partial_v\mathcal D_N
              +v^{\mathsf T}(Q_{\rm drv}+B_u u).
 \label{sm:general-power}
\end{equation}

\begin{align}
 &\int_0^L\!\rho A_c w_{tt}\eta\dd s
       +m_tw_{tt}(L)\eta(L)+J_t\ddot\vartheta\eta_s(L)\nonumber\\
 &+\alpha\left[
       \int_0^L\!\rho A_c w_t\eta\dd s
       +m_tw_t(L)\eta(L)+J_t\dot\vartheta\eta_s(L)\right]\nonumber\\
 &+\int_0^L\!EIw_{ss}\eta_{ss}\dd s
       =F\eta(L)+[\tau_B-\mu B_0\sin\vartheta]\eta_s(L).
 \label{sm:beam-weak}
\end{align}

\begin{equation}
 \det\begin{pmatrix}
 g_\lambda+\eta_t\lambda f&
 c_++\eta_t\lambda g_\lambda\\
 c_++h_\lambda s_+&
 s_++h_\lambda f
 \end{pmatrix}=0.
 \label{sm:characteristic-determinant}
\end{equation}

\begin{equation}
 \mathcal D(X,v)=
 \frac{\mathcal D_{\rm phys}(D_sX,\omega_0D_sv)}{E_0\omega_0}
 =\tfrac12\gamma v^{\mathsf T}\mathsf N^{-1}v.
 \label{sm:rayleigh-scale}
\end{equation}

\begin{align}
 \dot H_{0,N}
 &=-\alpha\|\dot a^{(N)}\|^2
       -\dot a^{(N)\mathsf T}\nabla_a\mathcal R_N\nonumber\\
 &\quad+F_{\rm app}\dot w(L)+\tau_{B,\rm app}\dot\vartheta_N.
 \label{sm:enriched-power}
\end{align}

\begin{align}
 a^{\rm des}_{1:2,tt}
 &=D_s\omega_0^2\bigl[
     (h_{\rm tar})_{YX}(h_{\rm tar})_Y
       -(h_{\rm tar})_{YY}(h_{\rm tar})_X\bigr],\nonumber\\
 \binom{F}{T}
 &=A_{\rm mag}^{-1}
   \bigl[a^{\rm des}_{1:2,tt}+\alpha v_{1:2}
                        +\Omega_2^2a_{1:2}\bigr],\nonumber\\
 B_y&=\frac{T-E_0(\vartheta-\sin\vartheta)}{\mu\cos\vartheta}.
 \label{app:full-feedback}
\end{align}

\begin{align}
 &\Delta Y^{\mathsf T}[h_Y(X,Y_1)-h_Y(X,Y_2)]\nonumber\\
 &\quad=\int_0^1
 \Delta Y^{\mathsf T}h_{YY}(X,Y_s)\Delta Y\dd s>0.
 \label{sm:velocity-injectivity}
\end{align}

\begin{align}
 r_e^{\mathsf T}v-\alpha v^{\mathsf T}M_fv
 &\le\frac{r_e^{\mathsf T}M_f^{-1}r_e}{4\alpha}\le p_e,\nonumber\\
 p_e&=\frac{(\epsilon_F\sqrt{m_F}
                  +\mu\epsilon_B\sqrt{m_\vartheta})^2}{4\alpha}.
 \label{sm:additive-power}
\end{align}

\begin{equation}\label{sr:shared-residual-bound}
\begin{aligned}
 B_g&=\cosh s_d-1-\tfrac12s_d^2,\\
 b_R^A, b_R^B&\le b_\beta B_g,\\
 \epsilon_A&\le\overline R_1+b_\beta B_g,\qquad
 \epsilon_B\le\overline R_{1.2}+b_\beta B_g.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:birkhoff-compatibility}
\begin{aligned}
 \partial_k\mathcal K_{ij}+\partial_i\mathcal K_{jk}
                       +\partial_j\mathcal K_{ki}&=0,\\
 \partial_t\mathcal K_{ij}&=\partial_i b_j-\partial_j b_i.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:primitive}
\begin{aligned}
 Y_+^{\mathsf T}\dd X_+-Y_-^{\mathsf T}\dd X_-
 &=\bar Y^{\mathsf T}\dd(\delta X)+\delta Y^{\mathsf T}\dd\bar X\\
 &=\dd(\bar Y^{\mathsf T}\delta X-S_\Delta).
\end{aligned}
\end{equation}

\begin{equation}\label{ss:central4-magnetic}
\begin{aligned}
 J\nabla S_\Delta^{[4]}
 &=\Delta\binom{v}{-u}+\frac{\Delta^3}{24}\binom{Q}{P},\\
 Q&=2\mathsf N A v,\\
 P&=\kappa\sin(s)b^2d-2A\mathsf N u.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:central4-magnetic-jacobian}
\begin{aligned}
 Q_X&=-2\kappa\sin(s)b(\mathsf N d)d^{\mathsf T},\\
 Q_Y&=2\mathsf N A\mathsf N,\\
 P_X&=\kappa[\cos(s)b^2\\
    &\quad+2\sin(s)d^{\mathsf T}\mathsf N u]dd^{\mathsf T}-2A\mathsf N A,\\
 P_Y&=2\kappa\sin(s)b\,d(\mathsf N d)^{\mathsf T}.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:quartic-generator}
 W_{4,\kappa}=
 \sum_{k\ne0}\frac{P_{4,k}(I)}{\mathrm i k\cdot\nu}
                 e^{\mathrm i k\cdot\phi}.
\end{equation}

\begin{equation}\label{ss:physical-defect}
\begin{aligned}
 e_\ell={}&\int_{a_\ell}^{b_\ell}
 [\dot c_{\ell Y}+\nabla V_0(c_{\ell X})]\dd\tau\\
 &+\int_{a_\ell}^{b_\ell}
 [\textstyle\sum_j\beta_{*,j}\nabla F_j(c_{\ell X})
  +\gamma c_{\ell Y}-U_\ell^{\rm data}]\dd\tau.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:full-readout}
\begin{aligned}
 F(x)&=\binom{g(d^{\mathsf T}X)/\norm{v_4}_2}{U_F^{\mathsf T}m_4(x)},\\
 h_\eta(x)&=h_2(x)+\eta^{\mathsf T}F(x),\\
 \eta&=(a\norm{v_4}_2,c),\qquad c\in\R^{34}.
\end{aligned}
\end{equation}

\begin{equation}\label{ss:general-reference-acceleration}
 \ddot a^{\rm ref}=\omega_0^2D_s
    (\widehat h_{YX}\widehat h_Y-\widehat h_{YY}\widehat h_X).
\end{equation}

\begin{equation}\label{tm:substitution}
\begin{aligned}
 Y'&=-\nabla V_*(X)-\gamma Y+U_B\\
   &=-\nabla\widehat V(X_r)-\kappa_p\mathsf N^{-1}e_X
          -\kappa_de_Y\\
   &\quad-\nabla\delta R(X)-\delta\gamma Y.
\end{aligned}
\end{equation}

