\begin{equation}\label{ctrl:midpoint}
\begin{aligned}
 X_+-X_-&=\Delta\mathsf N\bar Y,\\
 Y_+-Y_-&=-\Delta\nabla(V_0+R_*)(\bar X)
               -\Delta\gamma\bar Y\\
